32	/** Configuration of each supported algorithm. */
33	export const algorithms = /* @__PURE__ */ Object.freeze({
34	  "aes-128-ctr": /* @__PURE__ */ Object.freeze({
35	    keyBits: 128,
36	    ivBits: 128,
37	    name: "AES-CTR",
