56	
57	/** Serializes, encrypts, and signs objects into an iron protocol string. */
58	export async function seal(
59	  object: Readonly<unknown>,
60	  password: Readonly<RawPassword>,
61	  opts: Readonly<SealOptions>,
62	): Promise<string> {
63	  const now = Date.now() + (opts.localtimeOffsetMsec || 0);
64	
65	  if (!password) {
66	    throw new Error("Empty password");
67	  }
68	  const { id = "", encryption, integrity } = normalizePassword(password);
69	  if (id && !/^\w+$/.test(id)) {
70	    throw new Error("Invalid password id");
71	  }
72	
73	  // prettier-ignore
74	  const { encrypted, key } = await encrypt(encryption, opts.encryption, JSON.stringify(object));
75	
76	  const encryptedB64 = base64Encode(encrypted);
77	  const iv = base64Encode(key.iv);
78	  const expiration = opts.ttl ? now + opts.ttl : "";
79	  const macBaseString = `${macPrefix}*${id}*${key.salt}*${iv}*${encryptedB64}*${expiration}`;
80	
81	  const mac = await hmacWithPassword(integrity, opts.integrity, macBaseString);
82	  const sealed = `${macBaseString}*${mac.salt}*${mac.digest}`;
83	  return sealed;
84	}
85	
86	/** Verifies, decrypts, and reconstruct an iron protocol string into an object. */
87	export async function unseal(
88	  sealed: string,
89	  password: Password | PasswordHash,
90	  opts: Readonly<SealOptions>,
91	): Promise<unknown> {
92	  const now = Date.now() + (opts.localtimeOffsetMsec || 0);
93	
94	  if (!password) {
95	    throw new Error("Empty password");
96	  }
97	
98	  const parts = sealed.split("*");
99	  if (parts.length !== 8) {
100	    throw new Error("Incorrect number of sealed components");
101	  }
102	  // prettier-ignore
103	  const [prefix, passwordId, encryptionSalt, encryptionIv, encryptedB64, expiration, hmacSalt, hmac] = parts;
104	  const macBaseString = `${prefix}*${passwordId}*${encryptionSalt}*${encryptionIv}*${encryptedB64}*${expiration}`;
105	
106	  if (macPrefix !== prefix) {
107	    throw new Error("Wrong mac prefix");
108	  }
109	
110	  if (expiration) {
111	    if (!/^\d+$/.test(expiration)) {
112	      throw new Error("Invalid expiration");
113	    }
114	    const exp = Number.parseInt(expiration, 10);
115	    if (exp <= now - opts.timestampSkewSec * 1000) {
116	      throw new Error("Expired seal");
117	    }
118	  }
119	
120	  let pass: RawPassword = "";
121	  const _passwordId = passwordId || "default";
122	  if (typeof password === "string" || password instanceof Uint8Array) {
123	    pass = password;
124	  } else if (_passwordId in password) {
125	    pass = password[_passwordId]!;
126	  } else {
127	    throw new Error(`Cannot find password: ${_passwordId}`);
128	  }
129	
130	  pass = normalizePassword(pass);
131	
132	  // prettier-ignore
133	  const mac = await hmacWithPassword(pass.integrity, { ...opts.integrity, salt: hmacSalt }, macBaseString);
134	
135	  if (!fixedTimeComparison(mac.digest, hmac)) {
136	    throw new Error("Bad hmac value");
137	  }
138	
139	  const encrypted = base64Decode(encryptedB64);
140	
141	  const decryptOptions: GenerateKeyOptions<EncryptionAlgorithm> = {
142	    ...opts.encryption,
143	    salt: encryptionSalt,
144	    iv: base64Decode(encryptionIv),
145	  };
146	
147	  const decrypted = await decrypt(pass.encryption, decryptOptions, encrypted);
148	
149	  return decrypted ? JSON.parse(decrypted) : null;
150	}
151	
152	// --- hmac ---
153	
154	/** Calculates a HMAC digest. */
155	export async function hmacWithPassword(
156	  password: Readonly<Password>,
157	  options: Readonly<GenerateKeyOptions<IntegrityAlgorithm>>,
158	  data: string,
159	): Promise<HMacResult> {
160	  const key = await generateKey(password, { ...options, hmac: true });
161	  const textBuffer = textEncoder.encode(data);
162	  // prettier-ignore
163	  const signed = await crypto.subtle.sign({ name: "HMAC" }, key.key, textBuffer);
164	  const digest = base64Encode(new Uint8Array(signed));
165	  return { digest, salt: key.salt };
166	}
167	
168	// --- key generation ---
169	
170	/** Generates a key from the password. */
171	export async function generateKey(password: Password, options: GenerateKeyOptions): Promise<Key> {
172	  if (!password?.length) {
173	    throw new Error("Empty password");
174	  }
175	
176	  if (options == null || typeof options !== "object") throw new Error("Bad options");
177	  if (!(options.algorithm in algorithms))
178	    throw new Error(`Unknown algorithm: ${options.algorithm}`);
179	
180	  const algorithm = algorithms[options.algorithm];
181	
182	  let resultKey: Key["key"];
183	  let resultSalt: Key["salt"];
184	  let resultIV: Key["iv"];
185	
186	  const hmac = options.hmac ?? false;
187	  // prettier-ignore
188	  const id = hmac ? { name: "HMAC", hash: algorithm.name } : { name: algorithm.name };
