210	    resultSalt = salt;
211	  } else {
212	    if (password.length < algorithm.keyBits / 8) {
213	      throw new Error("Key buffer (password) too small");
214	    }
215	    // prettier-ignore
216	    resultKey = await crypto.subtle.importKey("raw", password, id, false, usage);
217	    resultSalt = "";
218	  }
219	
220	  if (options.iv) {
221	    resultIV = options.iv;
222	  } else if ("ivBits" in algorithm) {
223	    resultIV = randomBits(algorithm.ivBits);
224	  } else {
225	    throw new Error("Missing IV");
226	  }
227	
228	  return {
229	    key: resultKey,
230	    salt: resultSalt,
231	    iv: resultIV,
232	  } satisfies Key;
233	}
234	
235	/** Provides an asynchronous Password-Based Key Derivation Function 2 (PBKDF2) implementation. */
236	async function pbkdf2(
237	  password: string,
238	  salt: string,
239	  iterations: number,
240	  keyLength: number,
241	  hash: HashAlgorithmIdentifier,
242	): Promise<ArrayBuffer> {
243	  const passwordBuffer = textEncoder.encode(password);
244	  // prettier-ignore
245	  const importedKey = await crypto.subtle.importKey("raw", passwordBuffer, { name: "PBKDF2" }, false, ["deriveBits"]);
246	  const saltBuffer = textEncoder.encode(salt);
247	  const params = { name: "PBKDF2", hash, salt: saltBuffer, iterations };
248	  // prettier-ignore
249	  const derivation = await crypto.subtle.deriveBits(params, importedKey, keyLength * 8);
250	  return derivation;
251	}
252	
253	// --- encrypt/decrypt ---
254	
255	export async function encrypt(
256	  password: Password,
257	  options: GenerateKeyOptions<EncryptionAlgorithm>,
258	  data: string,
259	): Promise<{ encrypted: Uint8Array<ArrayBuffer>; key: Key }> {
260	  const key = await generateKey(password, options);
261	  const encrypted = await crypto.subtle.encrypt(...getEncryptParams(options.algorithm, key, data));
262	  return { encrypted: new Uint8Array(encrypted), key };
263	}
264	
265	export async function decrypt(
266	  password: Password,
267	  options: GenerateKeyOptions<EncryptionAlgorithm>,
268	  data: Uint8Array<ArrayBuffer> | string,
269	): Promise<string> {
270	  const key = await generateKey(password, options);
271	  const decrypted = await crypto.subtle.decrypt(...getEncryptParams(options.algorithm, key, data));
272	  return textDecoder.decode(decrypted);
273	}
274	
275	function getEncryptParams(
276	  algorithm: EncryptionAlgorithm,
277	  key: Key,
278	  data: Uint8Array<ArrayBuffer> | string,
279	): [AesCbcParams | AesCtrParams, CryptoKey, Uint8Array<ArrayBuffer>] {
280	  return [
281	    algorithm === "aes-128-ctr"
282	      ? ({
283	          name: "AES-CTR",
284	          counter: key.iv,
285	          length: 128,
286	        } satisfies AesCtrParams)
287	      : ({ name: "AES-CBC", iv: key.iv } satisfies AesCbcParams),
288	    key.key,
289	    typeof data === "string" ? textEncoder.encode(data) : data,
290	  ];
291	}
292	
293	// --- other utils ---
294	
295	/** Returns true if `a` is equal to `b`, without leaking timing information that would allow an attacker to guess one of the values. */
296	function fixedTimeComparison(a: string, b: string): boolean {
297	  let mismatch = a.length === b.length ? 0 : 1;
298	  if (mismatch) b = a;
299	  for (let i = 0; i < a.length; i += 1) mismatch |= a.charCodeAt(i) ^ b.charCodeAt(i);
300	  return mismatch === 0;
301	}
302	
303	/** Normalizes a password parameter. */
304	function normalizePassword(password: RawPassword) {
305	  if (typeof password === "string" || password instanceof Uint8Array) {
306	    return { encryption: password, integrity: password };
307	  }
308	  if ("secret" in password) {
309	    return {
310	      id: password.id,
311	      encryption: password.secret,
312	      integrity: password.secret,
313	    };
314	  }
315	  return {
316	    id: password.id,
317	    encryption: password.encryption,
318	    integrity: password.integrity,
319	  };
320	}
321	
322	/** Generate cryptographically strong pseudorandom bits. */
323	export function randomBits(bits: number): Uint8Array<ArrayBuffer> {
324	  if (bits < 1) throw new Error("Invalid random bits count");
325	  const bytes = Math.ceil(bits / 8);
326	  return randomBytes(bytes);
327	}
328	
329	/** Generates cryptographically strong pseudorandom bytes. */
330	function randomBytes(size: number): Uint8Array<ArrayBuffer> {
331	  const bytes = new Uint8Array(size);
332	  crypto.getRandomValues(bytes);
333	  return bytes;
334	}
335	
336	// --- Types ---
